<?php require_once '../includes/auth.php';require_login();verify_csrf();$u=user();$id=(int)($_POST['task_id']??0);$msg=trim($_POST['message']??'');$p=max(0,min(100,(int)($_POST['progress']??0)));$s=mysqli_prepare($conn,"SELECT t.title FROM work_tasks t JOIN task_assignees a ON a.task_id=t.id WHERE t.id=? AND a.user_id=?");mysqli_stmt_bind_param($s,'ii',$id,$u['id']);mysqli_stmt_execute($s);$task=mysqli_fetch_assoc(mysqli_stmt_get_result($s));if(!$task||$msg==='')exit('Invalid task update.');$s=mysqli_prepare($conn,"INSERT INTO task_replies(task_id,user_id,message,progress_percent) VALUES(?,?,?,?)");mysqli_stmt_bind_param($s,'iisi',$id,$u['id'],$msg,$p);mysqli_stmt_execute($s);$status=$p>=100?'submitted':'in_progress';$s=mysqli_prepare($conn,"UPDATE work_tasks SET progress_percent=?,status=? WHERE id=?");mysqli_stmt_bind_param($s,'isi',$p,$status,$id);mysqli_stmt_execute($s);log_activity('updated','work',$task['title'],$id);flash('success','Task update submitted.');redirect('view.php?id='.$id);
